c=np.arange(113)
def basis(ks,const=False):
    cols=sum(([np.cos(2*np.pi*k*c/113),np.sin(2*np.pi*k*c/113)] for k in ks),[])
    if const: cols=[np.ones(113)]+cols
    return np.stack(cols,1)
