def r2(Y,F):
    Y=np.asarray(Y,float); F=np.asarray(F,float)
    P=F@np.linalg.lstsq(F,Y,rcond=None)[0]
    return 1-np.sum((P-Y)**2)/np.sum((Y-Y.mean(0))**2)
